def keys_to_names(mask):
    """GBA key mask -> list of key names"""
    return [k for k, v in KEY_BITS.items() if mask & v]

# top-level fields that are entirely privileged (zero in visible mode); nested
# *_priv members of party/battlers/objects are covered by privileged_mask()
