def privileged_mask():
    """uint8 array of OBS_SIZE bytes: 1 where the byte belongs to a privileged field"""
    m = np.zeros(OBS_SIZE, dtype=np.uint8)
    for off, size in _PRIV_RANGES:
        m[off:off + size] = 1
    return m

